"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";
import {
  DEFAULT_LOCALE,
  type DateRange,
  addDays,
  addMonths,
  clampDate,
  endOfWeek,
  formatDate,
  getISOWeek,
  getMonthGrid,
  isAfterDay,
  isBeforeDay,
  isSameDay,
  isSameMonth,
  isToday,
  isWeekend,
  isWithin,
  monthName,
  startOfDay,
  startOfMonth,
  startOfWeek,
  weekdayNames,
} from "../lib/date";

export type CalendarMode = "single" | "range" | "multiple";

/**
 * De props die elke modus deelt. Geëxporteerd omdat de props-tabel in de docs
 * uit `export interface` gelezen wordt: `CalendarProps` zelf is een doorsnede
 * met een union en komt daar dus niet in terecht.
 */
export interface CalendarBaseProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  /** Zichtbare maand (controlled). */
  month?: Date;
  defaultMonth?: Date;
  onMonthChange?: (month: Date) => void;
  /** 0 = zondag, 1 = maandag (standaard). */
  weekStartsOn?: 0 | 1;
  /** Aantal maanden naast elkaar. */
  numberOfMonths?: number;
  min?: Date;
  max?: Date;
  /** Extra dagen uitschakelen, bv. feestdagen of weekends. */
  disabled?: (date: Date) => boolean;
  /** Toont de ISO-weeknummers in een extra kolom. */
  showWeekNumbers?: boolean;
  /** Verbergt de dagen van de vorige/volgende maand. */
  hideOutsideDays?: boolean;
  /** Klein bolletje onder een dag, bv. "er staat iets gepland". */
  markers?: (date: Date) => boolean;
  locale?: string;
  /** Inhoud onderaan de kalender, bv. knoppen. */
  footer?: React.ReactNode;
  size?: "sm" | "md";
}

/** Eén datum kiezen (de standaard). */
export interface CalendarSingleProps {
  mode?: "single";
  selected?: Date | null;
  onSelect?: (date: Date | null) => void;
}

/** Een periode kiezen: eerste klik zet `from`, tweede `to`. */
export interface CalendarRangeProps {
  mode: "range";
  selected?: DateRange | null;
  onSelect?: (range: DateRange) => void;
}

/** Losse dagen aan- en uitvinken. */
export interface CalendarMultipleProps {
  mode: "multiple";
  selected?: Date[];
  onSelect?: (dates: Date[]) => void;
}

export type CalendarProps = CalendarBaseProps &
  (CalendarSingleProps | CalendarRangeProps | CalendarMultipleProps);

/**
 * Calendar — maandkalender met enkelvoudige, bereik- en meervoudige selectie.
 * Volledig zelf geschreven: geen react-day-picker, geen date-bibliotheek.
 */
export const Calendar = React.forwardRef<HTMLDivElement, CalendarProps>(function Calendar(props, ref) {
  const {
    month,
    defaultMonth,
    onMonthChange,
    weekStartsOn = 1,
    numberOfMonths = 1,
    min,
    max,
    disabled,
    showWeekNumbers,
    hideOutsideDays,
    markers,
    locale = DEFAULT_LOCALE,
    footer,
    size = "md",
    className,
    mode = "single",
    selected,
    onSelect,
    ...rest
  } = props as CalendarBaseProps & {
    mode?: CalendarMode;
    selected?: Date | Date[] | DateRange | null;
    onSelect?: (value: never) => void;
  };

  const anchor = React.useMemo(() => firstSelected(mode, selected) ?? new Date(), [mode, selected]);
  const [internalMonth, setInternalMonth] = React.useState<Date>(() =>
    startOfMonth(defaultMonth ?? anchor)
  );
  const visibleMonth = month ? startOfMonth(month) : internalMonth;

  const [focused, setFocused] = React.useState<Date | null>(null);
  const [hovered, setHovered] = React.useState<Date | null>(null);
  const gridRef = React.useRef<HTMLDivElement>(null);

  const setMonth = (next: Date) => {
    const value = startOfMonth(next);
    if (!month) setInternalMonth(value);
    onMonthChange?.(value);
  };

  const isDisabled = React.useCallback(
    (date: Date) => {
      if (min && isBeforeDay(date, min)) return true;
      if (max && isAfterDay(date, max)) return true;
      return Boolean(disabled?.(date));
    },
    [min, max, disabled]
  );

  const pick = (date: Date) => {
    if (isDisabled(date)) return;
    const day = startOfDay(date);

    if (mode === "range") {
      const current = (selected ?? {}) as DateRange;
      const next: DateRange =
        !current.from || (current.from && current.to)
          ? { from: day, to: undefined }
          : isBeforeDay(day, current.from)
            ? { from: day, to: current.from }
            : { from: current.from, to: day };
      (onSelect as unknown as (value: DateRange) => void)?.(next);
      return;
    }

    if (mode === "multiple") {
      const current = ((selected as Date[]) ?? []).slice();
      const index = current.findIndex((entry) => isSameDay(entry, day));
      if (index === -1) current.push(day);
      else current.splice(index, 1);
      (onSelect as unknown as (value: Date[]) => void)?.(current);
      return;
    }

    const current = selected as Date | null | undefined;
    (onSelect as unknown as (value: Date | null) => void)?.(
      current && isSameDay(current, day) ? null : day
    );
  };

  const moveFocus = (base: Date, next: Date) => {
    const target = clampDate(next, min, max);
    setFocused(target);
    if (!isSameMonth(target, visibleMonth) && !isWithinVisible(target, visibleMonth, numberOfMonths)) {
      setMonth(startOfMonth(target));
    }
    window.setTimeout(() => {
      gridRef.current
        ?.querySelector<HTMLButtonElement>(`[data-day="${dayKey(target)}"]`)
        ?.focus({ preventScroll: true });
    }, 0);
    return base;
  };

  const onKeyDown = (event: React.KeyboardEvent, date: Date) => {
    const keys: Record<string, () => Date> = {
      ArrowLeft: () => addDays(date, -1),
      ArrowRight: () => addDays(date, 1),
      ArrowUp: () => addDays(date, -7),
      ArrowDown: () => addDays(date, 7),
      Home: () => startOfWeek(date, weekStartsOn),
      End: () => endOfWeek(date, weekStartsOn),
      PageUp: () => addMonths(date, event.shiftKey ? -12 : -1),
      PageDown: () => addMonths(date, event.shiftKey ? 12 : 1),
    };

    const handler = keys[event.key];
    if (handler) {
      event.preventDefault();
      moveFocus(date, handler());
      return;
    }
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      pick(date);
    }
  };

  const months = Array.from({ length: Math.max(1, numberOfMonths) }, (_, index) =>
    addMonths(visibleMonth, index)
  );
  const weekdays = weekdayNames(weekStartsOn, "short", locale);

  const canGoBack = !min || isBeforeDay(startOfMonth(visibleMonth), min) === false;
  const canGoForward =
    !max || isAfterDay(startOfMonth(addMonths(visibleMonth, months.length)), max) === false;

  return (
    <div
      ref={ref}
      className={cn("lui-calendar", `lui-calendar-${size}`, className)}
      role="group"
      aria-label="Kalender"
      {...rest}
    >
      <div className="lui-calendar-months" ref={gridRef}>
        {months.map((current, monthIndex) => (
          <div className="lui-calendar-month" key={current.toISOString()}>
            <div className="lui-calendar-header">
              {monthIndex === 0 ? (
                <button
                  type="button"
                  className="lui-calendar-nav"
                  aria-label="Vorige maand"
                  disabled={!canGoBack}
                  onClick={() => setMonth(addMonths(visibleMonth, -1))}
                >
                  <Icon name="chevronLeft" size={16} />
                </button>
              ) : (
                <span className="lui-calendar-nav-spacer" />
              )}

              <div className="lui-calendar-title" aria-live="polite">
                {monthName(current, locale)}
              </div>

              {monthIndex === months.length - 1 ? (
                <button
                  type="button"
                  className="lui-calendar-nav"
                  aria-label="Volgende maand"
                  disabled={!canGoForward}
                  onClick={() => setMonth(addMonths(visibleMonth, 1))}
                >
                  <Icon name="chevronRight" size={16} />
                </button>
              ) : (
                <span className="lui-calendar-nav-spacer" />
              )}
            </div>

            <div
              className={cn("lui-calendar-grid", showWeekNumbers && "lui-calendar-grid-weeks")}
              role="grid"
            >
              {showWeekNumbers && <div className="lui-calendar-weekhead" aria-hidden="true" />}
              {weekdays.map((day) => (
                <div className="lui-calendar-weekday" key={day} role="columnheader" aria-label={day}>
                  {day}
                </div>
              ))}

              {chunk(getMonthGrid(current, weekStartsOn), 7).map((week) => (
                <React.Fragment key={week[0].toISOString()}>
                  {showWeekNumbers && (
                    <div className="lui-calendar-weeknumber" aria-hidden="true">
                      {getISOWeek(week[0])}
                    </div>
                  )}
                  {week.map((date) => {
                    const outside = !isSameMonth(date, current);
                    if (outside && hideOutsideDays) {
                      return <div className="lui-calendar-day-empty" key={dayKey(date)} />;
                    }

                    const state = dayState(mode, selected, date, hovered);
                    const dayDisabled = isDisabled(date);
                    const isFocusTarget = focused
                      ? isSameDay(focused, date)
                      : state.selected || (!hasSelection(mode, selected) && isToday(date));

                    return (
                      <button
                        key={dayKey(date)}
                        type="button"
                        role="gridcell"
                        data-day={dayKey(date)}
                        tabIndex={isFocusTarget ? 0 : -1}
                        disabled={dayDisabled}
                        aria-selected={state.selected}
                        aria-current={isToday(date) ? "date" : undefined}
                        aria-label={formatDate(date, { dateStyle: "full" }, locale)}
                        data-outside={outside ? "" : undefined}
                        data-today={isToday(date) ? "" : undefined}
                        data-weekend={isWeekend(date) ? "" : undefined}
                        data-selected={state.selected ? "" : undefined}
                        data-range-start={state.rangeStart ? "" : undefined}
                        data-range-end={state.rangeEnd ? "" : undefined}
                        data-in-range={state.inRange ? "" : undefined}
                        className="lui-calendar-day"
                        onClick={() => pick(date)}
                        onFocus={() => setFocused(date)}
                        onMouseEnter={() => setHovered(date)}
                        onMouseLeave={() => setHovered(null)}
                        onKeyDown={(event) => onKeyDown(event, date)}
                      >
                        <span className="lui-calendar-day-label">{date.getDate()}</span>
                        {markers?.(date) && <span className="lui-calendar-marker" />}
                      </button>
                    );
                  })}
                </React.Fragment>
              ))}
            </div>
          </div>
        ))}
      </div>

      {footer && <div className="lui-calendar-footer">{footer}</div>}
    </div>
  );
});

/* ------------------------------------------------------------------ */
/* Hulpfuncties                                                        */
/* ------------------------------------------------------------------ */

function dayKey(date: Date): string {
  return `${date.getFullYear()}-${date.getMonth() + 1}-${date.getDate()}`;
}

function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  for (let index = 0; index < items.length; index += size) {
    result.push(items.slice(index, index + size));
  }
  return result;
}

function firstSelected(
  mode: CalendarMode,
  selected: Date | Date[] | DateRange | null | undefined
): Date | null {
  if (!selected) return null;
  if (mode === "range") return (selected as DateRange).from ?? null;
  if (mode === "multiple") return (selected as Date[])[0] ?? null;
  return selected as Date;
}

function hasSelection(
  mode: CalendarMode,
  selected: Date | Date[] | DateRange | null | undefined
): boolean {
  if (!selected) return false;
  if (mode === "range") return Boolean((selected as DateRange).from);
  if (mode === "multiple") return (selected as Date[]).length > 0;
  return true;
}

function isWithinVisible(date: Date, month: Date, count: number): boolean {
  for (let index = 0; index < count; index += 1) {
    if (isSameMonth(date, addMonths(month, index))) return true;
  }
  return false;
}

function dayState(
  mode: CalendarMode,
  selected: Date | Date[] | DateRange | null | undefined,
  date: Date,
  hovered: Date | null
) {
  if (mode === "range") {
    const range = (selected ?? {}) as DateRange;
    const to = range.to ?? (range.from && hovered ? hovered : undefined);
    const start = range.from && to && isBeforeDay(to, range.from) ? to : range.from;
    const end = range.from && to && isBeforeDay(to, range.from) ? range.from : to;

    return {
      selected: isSameDay(date, range.from) || isSameDay(date, range.to),
      rangeStart: isSameDay(date, start),
      rangeEnd: isSameDay(date, end),
      inRange: isWithin(date, start, end),
    };
  }

  if (mode === "multiple") {
    const dates = (selected as Date[]) ?? [];
    return {
      selected: dates.some((entry) => isSameDay(entry, date)),
      rangeStart: false,
      rangeEnd: false,
      inRange: false,
    };
  }

  return {
    selected: isSameDay(selected as Date | null | undefined, date),
    rangeStart: false,
    rangeEnd: false,
    inRange: false,
  };
}

/* ============================ Calendar ============================ */
.lui-calendar {
  --lui-day: 36px;
  display: inline-flex; flex-direction: column;
  background: var(--surface); color: var(--text);
  user-select: none;
}
.lui-calendar-sm { --lui-day: 30px; }

.lui-calendar-months { display: flex; gap: 26px; }
.lui-calendar-month { display: flex; flex-direction: column; gap: 8px; }

.lui-calendar-header {
  display: flex; align-items: center; gap: 6px;
  padding: 2px 2px 4px;
}
.lui-calendar-title {
  flex: 1; text-align: center;
  font-size: 13.5px; font-weight: 650; color: var(--text);
  letter-spacing: -0.01em; text-transform: capitalize;
}
.lui-calendar-nav {
  display: grid; place-items: center; flex: none;
  width: 28px; height: 28px; border-radius: var(--r-xs);
  border: 1px solid transparent; background: transparent;
  color: var(--text-2); cursor: pointer;
  transition: background var(--dur-fast), color var(--dur-fast);
}
.lui-calendar-nav:hover:not(:disabled) { background: var(--surface-3); color: var(--text); }
.lui-calendar-nav:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-calendar-nav:disabled { opacity: .35; cursor: not-allowed; }
.lui-calendar-nav-spacer { width: 28px; height: 28px; flex: none; }

.lui-calendar-grid {
  display: grid; grid-template-columns: repeat(7, var(--lui-day));
  gap: 2px;
}
.lui-calendar-grid-weeks { grid-template-columns: 26px repeat(7, var(--lui-day)); }

.lui-calendar-weekday, .lui-calendar-weekhead {
  display: grid; place-items: center; height: 26px;
  font-size: 11px; font-weight: 650; color: var(--text-3);
  text-transform: lowercase;
}
.lui-calendar-weeknumber {
  display: grid; place-items: center; height: var(--lui-day);
  font-size: 10.5px; font-weight: 600; color: var(--text-3);
  font-family: var(--mono);
}

.lui-calendar-day-empty { width: var(--lui-day); height: var(--lui-day); }

.lui-calendar-day {
  position: relative;
  width: var(--lui-day); height: var(--lui-day);
  display: grid; place-items: center;
  border: 1px solid transparent; background: transparent;
  border-radius: var(--r-sm);
  font: inherit; font-size: 13px; font-weight: 550;
  color: var(--text); cursor: pointer;
  transition: background var(--dur-fast), color var(--dur-fast), border-color var(--dur-fast);
}
.lui-calendar-day:hover:not(:disabled) { background: var(--surface-3); }
.lui-calendar-day:focus-visible { outline: none; box-shadow: var(--ring); z-index: 1; }
.lui-calendar-day:disabled { color: var(--text-3); opacity: .4; cursor: not-allowed; }
.lui-calendar-day[data-outside] { color: var(--text-3); }
.lui-calendar-day[data-weekend]:not([data-selected]) { color: var(--text-2); }

.lui-calendar-day[data-today]:not([data-selected]) {
  border-color: var(--accent-border); color: var(--accent-active); font-weight: 650;
}

.lui-calendar-day[data-in-range] {
  background: var(--accent-tint); border-radius: 0; color: var(--accent-active);
}
.lui-calendar-day[data-range-start] { border-radius: var(--r-sm) 0 0 var(--r-sm); }
.lui-calendar-day[data-range-end] { border-radius: 0 var(--r-sm) var(--r-sm) 0; }
.lui-calendar-day[data-range-start][data-range-end] { border-radius: var(--r-sm); }

.lui-calendar-day[data-selected] {
  background: var(--accent); border-color: var(--accent);
  color: var(--accent-fg); font-weight: 650;
}
.lui-calendar-day[data-selected]:hover { background: var(--accent-hover); }

.lui-calendar-marker {
  position: absolute; bottom: 4px; left: 50%; transform: translateX(-50%);
  width: 4px; height: 4px; border-radius: var(--r-full); background: var(--accent);
}
.lui-calendar-day[data-selected] .lui-calendar-marker { background: var(--accent-fg); }

.lui-calendar-footer {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--border);
}

@media (max-width: 560px) {
  .lui-calendar-months { flex-direction: column; gap: 18px; }
}

/**
 * Datumhulpfuncties — eigen implementatie op basis van de ingebouwde Date en
 * Intl. Geen date-fns, geen dayjs, geen luxon.
 *
 * Alle functies werken met lokale tijd en laten de meegegeven Date ongemoeid.
 */

export interface DateRange {
  from?: Date;
  to?: Date;
}

/** Standaardtaal van het Dafke UI-design. */
export const DEFAULT_LOCALE = "nl-BE";

/* ------------------------------------------------------------------ */
/* Basis                                                               */
/* ------------------------------------------------------------------ */

export function startOfDay(date: Date): Date {
  const copy = new Date(date);
  copy.setHours(0, 0, 0, 0);
  return copy;
}

export function addDays(date: Date, amount: number): Date {
  const copy = new Date(date);
  copy.setDate(copy.getDate() + amount);
  return copy;
}

export function addMonths(date: Date, amount: number): Date {
  const copy = new Date(date);
  const day = copy.getDate();
  copy.setDate(1);
  copy.setMonth(copy.getMonth() + amount);
  copy.setDate(Math.min(day, daysInMonth(copy)));
  return copy;
}

export function daysInMonth(date: Date): number {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
}

export function startOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), 1);
}

export function endOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0, 23, 59, 59, 999);
}

/** weekStartsOn: 0 = zondag, 1 = maandag (standaard in België). */
export function startOfWeek(date: Date, weekStartsOn = 1): Date {
  const copy = startOfDay(date);
  const diff = (copy.getDay() - weekStartsOn + 7) % 7;
  return addDays(copy, -diff);
}

export function endOfWeek(date: Date, weekStartsOn = 1): Date {
  return addDays(startOfWeek(date, weekStartsOn), 6);
}

/* ------------------------------------------------------------------ */
/* Vergelijken                                                         */
/* ------------------------------------------------------------------ */

export function isSameDay(a?: Date | null, b?: Date | null): boolean {
  if (!a || !b) return false;
  return (
    a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
  );
}

export function isSameMonth(a?: Date | null, b?: Date | null): boolean {
  if (!a || !b) return false;
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
}

export function isToday(date: Date): boolean {
  return isSameDay(date, new Date());
}

export function isWeekend(date: Date): boolean {
  const day = date.getDay();
  return day === 0 || day === 6;
}

export function isBeforeDay(a: Date, b: Date): boolean {
  return startOfDay(a).getTime() < startOfDay(b).getTime();
}

export function isAfterDay(a: Date, b: Date): boolean {
  return startOfDay(a).getTime() > startOfDay(b).getTime();
}

export function isWithin(date: Date, from?: Date | null, to?: Date | null): boolean {
  if (!from || !to) return false;
  const time = startOfDay(date).getTime();
  const start = startOfDay(from).getTime();
  const end = startOfDay(to).getTime();
  return time >= Math.min(start, end) && time <= Math.max(start, end);
}

export function clampDate(date: Date, min?: Date | null, max?: Date | null): Date {
  if (min && isBeforeDay(date, min)) return new Date(min);
  if (max && isAfterDay(date, max)) return new Date(max);
  return date;
}

/** Aantal hele dagen tussen twee datums (b - a). */
export function differenceInDays(a: Date, b: Date): number {
  const millis = startOfDay(b).getTime() - startOfDay(a).getTime();
  return Math.round(millis / 86_400_000);
}

/* ------------------------------------------------------------------ */
/* Weeknummer (ISO 8601)                                               */
/* ------------------------------------------------------------------ */

export function getISOWeek(date: Date): number {
  const target = startOfDay(date);
  // Donderdag van deze week bepaalt het jaar.
  target.setDate(target.getDate() + 3 - ((target.getDay() + 6) % 7));
  const firstThursday = new Date(target.getFullYear(), 0, 4);
  firstThursday.setDate(firstThursday.getDate() + 3 - ((firstThursday.getDay() + 6) % 7));
  return 1 + Math.round((target.getTime() - firstThursday.getTime()) / (7 * 86_400_000));
}

/* ------------------------------------------------------------------ */
/* Rasters                                                             */
/* ------------------------------------------------------------------ */

/** Alle dagen van de maand, aangevuld tot volledige weken (6 × 7 = 42 dagen). */
export function getMonthGrid(month: Date, weekStartsOn = 1): Date[] {
  const first = startOfWeek(startOfMonth(month), weekStartsOn);
  return Array.from({ length: 42 }, (_, index) => addDays(first, index));
}

/** De zeven (of minder) dagen van een week vanaf een datum. */
export function getWeekDays(date: Date, weekStartsOn = 1, length = 7): Date[] {
  const first = startOfWeek(date, weekStartsOn);
  return Array.from({ length }, (_, index) => addDays(first, index));
}

/* ------------------------------------------------------------------ */
/* Formatteren                                                         */
/* ------------------------------------------------------------------ */

const formatterCache = new Map<string, Intl.DateTimeFormat>();

function formatter(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let cached = formatterCache.get(key);
  if (!cached) {
    cached = new Intl.DateTimeFormat(locale, options);
    formatterCache.set(key, cached);
  }
  return cached;
}

export function formatDate(
  date: Date,
  options: Intl.DateTimeFormatOptions = { day: "2-digit", month: "short", year: "numeric" },
  locale: string = DEFAULT_LOCALE
): string {
  return formatter(locale, options).format(date);
}

/** "16 – 20 mrt 2026" of "28 feb – 3 mrt 2026" bij een maandgrens. */
export function formatDateRange(range: DateRange, locale: string = DEFAULT_LOCALE): string {
  if (!range.from) return "";
  if (!range.to || isSameDay(range.from, range.to)) return formatDate(range.from, undefined, locale);

  const sameMonth = isSameMonth(range.from, range.to);
  const sameYear = range.from.getFullYear() === range.to.getFullYear();

  const left = formatDate(
    range.from,
    sameMonth
      ? { day: "numeric" }
      : sameYear
        ? { day: "numeric", month: "short" }
        : { day: "numeric", month: "short", year: "numeric" },
    locale
  );
  const right = formatDate(range.to, { day: "numeric", month: "short", year: "numeric" }, locale);
  return `${left} – ${right}`;
}

/** Namen van de weekdagen, beginnend bij weekStartsOn. */
export function weekdayNames(
  weekStartsOn = 1,
  format: "narrow" | "short" | "long" = "short",
  locale: string = DEFAULT_LOCALE
): string[] {
  const base = new Date(2024, 0, 7); // een zondag
  return Array.from({ length: 7 }, (_, index) =>
    formatter(locale, { weekday: format }).format(addDays(base, (index + weekStartsOn) % 7))
  );
}

export function monthName(month: Date, locale: string = DEFAULT_LOCALE): string {
  return formatDate(month, { month: "long", year: "numeric" }, locale);
}

/* ------------------------------------------------------------------ */
/* Tijd (minuten sinds middernacht)                                     */
/* ------------------------------------------------------------------ */

/** "9:30", "930", "9.30" of "0930" → 570. Geeft null bij onleesbare invoer. */
export function parseTime(input: string): number | null {
  const clean = input.trim().replace(/[.,]/g, ":");
  if (!clean) return null;

  const withSeparator = clean.match(/^(\d{1,2}):(\d{1,2})$/);
  if (withSeparator) {
    return toMinutes(Number(withSeparator[1]), Number(withSeparator[2]));
  }

  const digits = clean.replace(/\D/g, "");
  if (!digits) return null;
  if (digits.length <= 2) return toMinutes(Number(digits), 0);
  if (digits.length === 3) return toMinutes(Number(digits.slice(0, 1)), Number(digits.slice(1)));
  return toMinutes(Number(digits.slice(0, 2)), Number(digits.slice(2, 4)));
}

function toMinutes(hours: number, minutes: number): number | null {
  if (!Number.isFinite(hours) || !Number.isFinite(minutes)) return null;
  if (hours > 23 || minutes > 59) return null;
  return hours * 60 + minutes;
}

/** 570 → "09:30". */
export function formatTime(minutes: number): string {
  const total = ((Math.round(minutes) % 1440) + 1440) % 1440;
  const hours = Math.floor(total / 60);
  const rest = total % 60;
  return `${String(hours).padStart(2, "0")}:${String(rest).padStart(2, "0")}`;
}

/** Rondt af op een veelvoud van `step` minuten. */
export function roundToStep(minutes: number, step: number): number {
  if (step <= 0) return minutes;
  return Math.round(minutes / step) * step;
}

/** Alle tijdstippen tussen from en to, met stappen van `step` minuten. */
export function timeSlots(from: number, to: number, step: number): number[] {
  const slots: number[] = [];
  for (let minutes = from; minutes <= to; minutes += step) slots.push(minutes);
  return slots;
}

/** "2 u 30" — leesbare duur voor diensten en verlof. */
export function formatDuration(minutes: number): string {
  const hours = Math.floor(minutes / 60);
  const rest = Math.round(minutes % 60);
  if (hours === 0) return `${rest} min`;
  if (rest === 0) return `${hours} u`;
  return `${hours} u ${rest}`;
}
